input.old_string:
const OPEN = '08:00'
const CLOSE = '22:00'

// reservation: { room: 'A', start: '09:00', end: '10:30' }（その日の時刻）
// 返り値: { ok: true } または { ok: false, code: 'INVALID_RANGE' | 'OUT_OF_HOURS' | 'OVERLAP' }
export function canBook(existing, request) {
  if (request.start >= request.end) return { ok: false, code: 'INVALID_RANGE' }
  if (request.start < OPEN || request.end > CLOSE) return { ok: false, code: 'OUT_OF_HOURS' }
  for (const r of existing) {
    if (r.room !== request.room) continue
    if (request.start < r.end && r.start < request.end) return { ok: false, code: 'OVERLAP' }
  }
  return { ok: true }
}

input.new_string:
const OPEN = toMinutes('08:00')
const CLOSE = toMinutes('22:00')
const CLEANUP_BUFFER = 15 // 分。同室の前後の予約との間に空けるべき清掃時間

// '9:30' 'H:MM' でも '09:30' 'HH:MM' でも受け付け、0時からの分数に変換する
function toMinutes(time) {
  const [h, m] = time.split(':')
  return Number(h) * 60 + Number(m)
}

// reservation: { room: 'A', start: '09:00', end: '10:30' }（その日の時刻。'9:30' 形式も可）
// 返り値: { ok: true } または { ok: false, code: 'INVALID_RANGE' | 'OUT_OF_HOURS' | 'OVERLAP' }
export function canBook(existing, request) {
  const start = toMinutes(request.start)
  const end = toMinutes(request.end)
  if (start >= end) return { ok: false, code: 'INVALID_RANGE' }
  if (start < OPEN || end > CLOSE) return { ok: false, code: 'OUT_OF_HOURS' }
  for (const r of existing) {
    if (r.room !== request.room) continue
    const rStart = toMinutes(r.start)
    const rEnd = toMinutes(r.end)
    if (start < rEnd + CLEANUP_BUFFER && rStart < end + CLEANUP_BUFFER) return { ok: false, code: 'OVERLAP' }
  }
  return { ok: true }
}

