test('別の部屋なら予約できる', () => {
  assert.deepEqual(canBook(existing, { room: 'B', start: '09:30', end: '10:30' }), { ok: true })
})

test('同室で終了時刻ちょうどに開始は清掃時間不足で OVERLAP', () => {
  assert.deepEqual(canBook(existing, { room: 'A', start: '10:00', end: '10:30' }), { ok: false, code: 'OVERLAP' })
})

test('同室で14分しか空いていない場合（前の予約の後）は OVERLAP', () => {
  assert.deepEqual(canBook(existing, { room: 'A', start: '10:14', end: '10:30' }), { ok: false, code: 'OVERLAP' })
})

test('同室で14分しか空いていない場合（前の予約の前）は OVERLAP', () => {
  assert.deepEqual(canBook(existing, { room: 'A', start: '08:30', end: '08:46' }), { ok: false, code: 'OVERLAP' })
})

test('同室でちょうど15分空いていれば予約できる（前の予約の後）', () => {
  assert.deepEqual(canBook(existing, { room: 'A', start: '10:15', end: '10:45' }), { ok: true })
})

test('同室でちょうど15分空いていれば予約できる（前の予約の前）', () => {
