})

test('別の部屋なら終了時刻ちょうどに開始しても清掃時間の影響を受けない', () => {
  assert.deepEqual(canBook(existing, { room: 'B', start: '10:00', end: '10:30' }), { ok: true })
})

test('1桁時の時刻表記でも正しく範囲判定できる（INVALID_RANGE 誤検知の回帰）', () => {
  assert.deepEqual(canBook([], { room: 'A', start: '9:30', end: '11:00' }), { ok: true })
})

test('1桁時の時刻表記で営業時間外を正しく検出できる（OUT_OF_HOURS の回帰）', () => {
  assert.deepEqual(canBook([], { room: 'A', start: '7:30', end: '9:00' }), { ok: false, code: 'OUT_OF_HOURS' })
})

test('既存予約が未ゼロ埋め表記でも重複を検出できる', () => {
  const mixed = [{ room: 'B', start: '9:00', end: '10:00' }]
  assert.deepEqual(canBook(mixed, { room: 'B', start: '09:45', end: '10:15' }), { ok: false, code: 'OVERLAP' })
})

